function extractIssueTypes(text) {
   var lines = String(text).split(/\r?\n/);
   for (var i = 0; i < lines.length; i++) {
       var m = /^on:[ \t]*(.*)$/.exec(lines[i]);
       if (!m || m[1].replace(/[ \t]+#.*$/, '').trim() !== '') continue;
       var childIndent = -1;
       for (var j = i + 1; j < lines.length; j++) {
           var line = lines[j];
           if (line.trim() === '') continue;
           var indent = indentOf(line);
           if (indent === 0) break;
           var km = KEY_LINE_RE.exec(line.trim());
           if (!km) continue;
           if (childIndent === -1) childIndent = indent;
           if (indent !== childIndent) continue;
           if (unquote(km[2].trim()) !== 'issues') continue;
           // inside issues: block — find types:
           var typesIndent = -1;
           for (var k = j + 1; k < lines.length; k++) {
               var tl = lines[k];
               if (tl.trim() === '') continue;
               var ti = indentOf(tl);
               if (ti <= indent) break; // dedent out of issues block
               var tkm = KEY_LINE_RE.exec(tl.trim());
               if (!tkm) continue;
               if (typesIndent === -1) typesIndent = ti;
               if (ti !== typesIndent) continue;
               if (unquote(tkm[2].trim()) !== 'types') continue;
