```js
/**
 * The `types:` list of the `issues:` trigger, e.g. ['assigned']. Parses
 * the flow form (types: [assigned, labeled]) and the block list form
 * (types:\n - assigned). Returns null when the file has no issues
 * trigger or the issues trigger declares no types key.
 */
function extractIssueTypes(text) {
   var lines = String(text).split(/\r?\n/);
   for (var i = 0; i < lines.length; i++) {
       var m = /^on:[ \t]*(.*)$/.exec(lines[i]);
       if (!m) continue;
       if (m[1].replace(/[ \t]+#.*$/, '').trim() !== '') {
           continue; // flow form carries no per-trigger options
       }
       var childIndent = -1;
       for (var j = i + 1; j < lines.length; j++) {
           var line = lines[j];
           if (line.trim() === '') continue;
           var indent = indentOf(line);
           if (indent === 0) break;
           var km = KEY_LINE_RE.exec(line.trim());
           if (!km) continue;
           if (childIndent === -1) childIndent = indent;
           if (indent !== childIndent) continue;
           if (unquote(km[2].trim()) !== 'issues') continue;
           // Inside the issues: block — the first `types:` key at its own
           // indent level; a dedent back to the issues level ends the scan.
           var typesIndent = -1;
           for (var k = j + 1; k < lines.length; k++) {
               var tl = lines[k];
               if (tl.trim() === '') continue;
               var ti = indentOf(tl);
               if (ti <= indent) break;
               var tkm = KEY_LINE_RE.exec(tl.trim());
               if (!tkm) continue;
               if (typesIndent === -1) typesIndent = ti;
               if (ti !== typesIndent) continue;
               if (unquote(tkm[2].trim()) !== 'types') continue;
               var inline = (tkm[3] || '').replace(/[ \t]+#.*$/, '').trim();
               if (inline.charAt(0) === '[') {
                   return flowItems(inline);
               }
               // Block list form: `- item` entries deeper than types:.
               var items = [];
               for (var q = k + 1; q < lines.length; q++) {
                   var ql = lines[q];
                   if (ql.trim() === '') continue;
                   var qi = indentOf(ql);
                   if (qi <= ti) break;
                   var qm = /^-[ \t]+(.*?)[ \t]*$/.exec(ql.trim());
                   if (qm) items.push(unquote(qm[1].replace(/[ \t]+#.*$/, '').trim()));
               }
               return items;
           }
           return null; // issues: block without a types: key
       }
       return null; // no issues: trigger
   }
   return null;
}
```

