function flowItems(inline) {
   var flow = inline.replace(/^\[[ \t]*/, '').replace(/[ \t]*\].*$/, '');
   var parts = flow === '' ? [] : flow.split(',');
   var out = [];
   for (var i = 0; i < parts.length; i++) {
       var item = parts[i].replace(/[ \t]+#.*$/, '').trim();
       if (item !== '') out.push(unquote(item));
   }
   return out;
}
```

