        assert.deepEqual(lint.findDuplicateKeys(yml), []);
    });

    test('folded scalar (run-name: >-) content never produces keys', function () {
        var yml = [
            'run-name: >-',
            "  tick {0}: schedule || ''",
            'on:',
            '  workflow_dispatch:',
            'jobs: {}'
        ].join('\n');
        assert.deepEqual(lint.findDuplicateKeys(yml), []);
    });

    test('a dedent below the scalar indent ends the scalar', function () {
        var yml = [
            'jobs:',
            '  a:',
            '    steps:',
            '      - run: |',
            '          key: inside-scalar',
            '    runs-on: ubuntu-latest',
            '    runs-on: ubuntu-latest'
        ].join('\n');
