        for (var j = i + 1; j < lines.length; j++) {
            var line = lines[j];
            if (line.trim() === '') {
                continue;
            }
            if (line.trim().charAt(0) === '#') {
                continue;
            }
            var indent = indentOf(line);
            if (indent === 0) {
                break;
            }
            var km = KEY_LINE_RE.exec(line.trim());
            if (!km) {
                continue;
            }
            if (childIndent === -1) {
                childIndent = indent;
            }
            if (indent !== childIndent) {
                continue;
            }
            if (unquote(km[2].trim()) !== 'issues') {
                continue;
            }
            // Inside the issues: block — the first `types:` key at its own
            // indent level; a dedent back to the issues level ends the scan.
            var typesIndent = -1;
            for (var k = j + 1; k < lines.length; k++) {
                var tl = lines[k];
                if (tl.trim() === '') {
                    continue;
                }
                if (tl.trim().charAt(0) === '#') {
                    continue;
                }
                var ti = indentOf(tl);
                if (ti <= indent) {
                    break;
                }
                var tkm = KEY_LINE_RE.exec(tl.trim());
                if (!tkm) {
                    continue;
                }
                if (typesIndent === -1) {
                    typesIndent = ti;
                }
                if (ti !== typesIndent) {
                    continue;
                }
                if (unquote(tkm[2].trim()) !== 'types') {
                    continue;
                }
                var inline = (tkm[3] || '').replace(/[ \t]+#.*$/, '').trim();
